package com.androidhit.lumadrift.social;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import com.androidhit.lumadrift.data.GameStore;
import com.androidhit.lumadrift.identity.AccountActivity;
import com.androidhit.lumadrift.ui.SceneActionView;
import com.androidhit.lumadrift.ui.ScenicUi;
import org.json.JSONObject;

/** Consent-first friend code exchange and finite daily gifts. No public directory or contact access. */
public final class SocialActivity extends Activity {
    private static final int BG=com.androidhit.lumadrift.ui.PulseUi124.BACKGROUND,CARD=com.androidhit.lumadrift.ui.PulseUi124.WHITE,WHITE=com.androidhit.lumadrift.ui.PulseUi124.INK,MINT=com.androidhit.lumadrift.ui.PulseUi124.BLUE_INK,MUTED=com.androidhit.lumadrift.ui.PulseUi124.MUTED,PEACH=com.androidhit.lumadrift.ui.PulseUi124.CORAL_INK;
    private GameStore store;private SocialClient client;private LinearLayout body;private TextView status;private SocialClient.Snapshot snapshot;private boolean busy,destroyed;
    private String t(String fr,String en,Object...args){return SocialStrings.get(store.resolvedLanguage(),fr,en,args);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);store=new GameStore(this);client=new SocialClient(this);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);render();}
    @Override public void onResume(){super.onResume();if(client!=null)refresh();}
    private void render(){
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackground(SceneActionView.atmosphere());
        scroll.setOnApplyWindowInsetsListener((v,insets)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets s=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(s.left,s.top,s.right,s.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        FrameLayout center=new FrameLayout(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(22),dp(16),dp(22),dp(36));center.addView(body,new FrameLayout.LayoutParams(Math.min(getResources().getDisplayMetrics().widthPixels,dp(540)),-2,Gravity.TOP|Gravity.CENTER_HORIZONTAL));scroll.addView(center);setContentView(scroll);
        button(body,"‹  "+t("Accueil","Home"),this::finish,MINT);label(body,"LUMA CIRCLE",15,MINT);label(body,t("Les étoiles se retrouvent","Stars find each other"),31,WHITE);
        label(body,t("Ajoute un ami avec son code. Offre un petit indice pour son prochain plateau.","Add a friend with their code. Send a little hint for their next board."),16,MUTED);
        status=label(body,busy?t("Connexion…","Connecting…"):"",14,PEACH);
        if(!SocialClient.configured()){status.setText(error("SOCIAL_NOT_CONFIGURED"));return;}
        if(client.uid().isEmpty()){label(body,t("Ton aventure reste jouable sans compte. Connecte-toi à Google pour créer ton cercle.","Your adventure stays playable without an account. Sign in with Google to create your circle."),16,WHITE);button(body,t("Mon compte Google","My Google account"),()->startActivity(new Intent(this,AccountActivity.class)),MINT);return;}
        if(snapshot==null){button(body,t("Actualiser","Refresh"),this::refresh,MINT);return;}
        LinearLayout profile=card();label(profile,t("TON CODE AMI","YOUR FRIEND CODE"),12,MINT);TextView code=label(profile,snapshot.code.substring(0,4)+" "+snapshot.code.substring(4,8)+" "+snapshot.code.substring(8,12)+" "+snapshot.code.substring(12),21,WHITE);code.setTextIsSelectable(true);
        button(profile,t("Copier le code","Copy code"),()->{ClipboardManager clipboard=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("Luma Drift",snapshot.code));Toast.makeText(this,t("Code copié","Code copied"),Toast.LENGTH_SHORT).show();},MINT);
        EditText nickname=new EditText(this);nickname.setTypeface(com.androidhit.lumadrift.ui.PulseUi124.face(400));nickname.setSingleLine(true);nickname.setText(snapshot.nickname);nickname.setTextColor(WHITE);nickname.setHintTextColor(MUTED);nickname.setHint(t("Ton surnom public","Your public nickname"));nickname.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(32)});profile.addView(nickname);
        SceneActionView.Toggle share=new SceneActionView.Toggle(this);share.setText(t("Partager ma position sur la carte","Share my map position"));share.setTextColor(WHITE);share.setTextSize(15);share.setChecked(snapshot.shareProgress);profile.addView(share);
        label(profile,t("Seuls tes amis acceptés voient ton surnom et ton compagnon. Ta position est masquée tant que tu ne l'actives pas. La progression est déclarée par ton appareil.","Only accepted friends see your nickname and companion. Your position stays hidden until you enable it. Progress is reported by your device."),13,MUTED);
        button(profile,t("Enregistrer mon profil","Save my profile"),()->perform(callback->client.updateProfile(nickname.getText().toString(),store.equippedCharacter(),store.unlockedLevel(),share.isChecked(),callback)),PEACH);
        LinearLayout add=card();label(add,t("Une nouvelle étoile","A new star"),22,WHITE);EditText input=new EditText(this);input.setTypeface(com.androidhit.lumadrift.ui.PulseUi124.face(400));input.setTextColor(WHITE);input.setHintTextColor(MUTED);input.setHint(t("Code de ton ami · 16 caractères","Friend code · 16 characters"));input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(24)});add.addView(input);button(add,t("Envoyer une invitation","Send invitation"),()->perform(callback->client.invite(input.getText().toString(),callback)),MINT);
        label(body,t("CADEAUX DU JOUR","TODAY'S GIFTS"),14,MINT);label(body,t("%d / 3 envois restants · 1 cadeau par ami et par jour UTC","%d / 3 sends left · 1 gift per friend per UTC day",snapshot.giftsRemaining),14,MUTED);label(body,t("Chaque cadeau contient 1 indice gagné, jamais de LumaGold. 5 réceptions par jour maximum, disponibles 7 jours.","Each gift contains 1 earned hint, never LumaGold. Receive up to 5 per day, available for 7 days."),14,MUTED);
        for(SocialClient.Gift gift:snapshot.gifts){LinearLayout card=card();label(card,"✦  "+gift.fromName+"  →  "+t("1 indice","1 hint"),18,WHITE);button(card,gift.claimed?t("Vérifier la réception","Check delivery"):t("Recevoir l'indice","Receive hint"),()->claim(gift),gift.claimed?MUTED:PEACH);}
        if(snapshot.gifts.isEmpty())label(body,t("Ta boîte à étoiles est vide pour le moment.","Your star mailbox is empty for now."),14,MUTED);
        label(body,t("INVITATIONS REÇUES · ","INVITATIONS RECEIVED · ")+snapshot.incoming.size(),14,MINT);
        for(SocialClient.Friend friend:snapshot.incoming){LinearLayout card=card();label(card,"✦  "+friend.nickname,20,WHITE);button(card,t("Accepter","Accept"),()->perform(callback->client.respond(friend.code,true,callback)),MINT);button(card,t("Refuser","Decline"),()->perform(callback->client.respond(friend.code,false,callback)),MUTED);}
        label(body,t("TON CERCLE · ","YOUR CIRCLE · ")+snapshot.friends.size()+" / 40",14,MINT);
        for(SocialClient.Friend friend:snapshot.friends){LinearLayout card=card();label(card,"✦  "+friend.nickname,22,WHITE);label(card,friend.level>0?t("Sur la carte : niveau ","On the map: level ")+friend.level:t("Position privée","Private position"),14,MUTED);button(card,t("Offrir 1 indice","Gift 1 hint"),()->perform(callback->client.sendGift(friend.code,callback)),PEACH);button(card,t("Retirer du cercle","Remove friend"),()->SceneActionView.showChoices(this,t("Retirer cet ami ?","Remove this friend?"),friend.nickname,new SceneActionView.Choice(t("Annuler","Cancel"),ScenicUi.Kind.CANCEL,null),new SceneActionView.Choice(t("Retirer","Remove"),ScenicUi.Kind.CONFIRM,ScenicUi.CORAL,()->perform(callback->client.remove(friend.code,callback)))),MUTED);}
        if(snapshot.friends.isEmpty())label(body,t("Partage ton code pour voir tes amis ici et sur la carte s'ils partagent leur position.","Share your code to see friends here and on the map when they share their position."),15,MUTED);
        label(body,t("INVITATIONS ENVOYÉES · ","INVITATIONS SENT · ")+snapshot.outgoing.size(),14,MINT);
        for(SocialClient.Friend friend:snapshot.outgoing){LinearLayout card=card();label(card,friend.nickname,18,WHITE);button(card,t("Annuler l'invitation","Cancel invitation"),()->perform(callback->client.remove(friend.code,callback)),MUTED);}
        button(body,t("Actualiser le cercle","Refresh circle"),this::refresh,MINT);
    }
    private interface Action {void run(SocialClient.Callback callback);}
    private void perform(Action action){if(busy)return;busy=true;status.setText(t("Envoi…","Sending…"));action.run(new SocialClient.Callback(){public void onSuccess(JSONObject result){busy=false;refresh();}public void onError(String code){busy=false;status.setText(error(code));}});}
    private void claim(SocialClient.Gift gift){if(busy)return;busy=true;String uid=client.uid();status.setText(t("Réception…","Receiving…"));client.claim(gift.id,new SocialClient.Callback(){public void onSuccess(JSONObject result){busy=false;try{JSONObject grant=result.getJSONObject("grant");if(!uid.equals(client.uid())||!gift.id.equals(grant.getString("id"))||!"power".equals(grant.getString("kind"))||!"hint".equals(grant.getString("itemId"))||grant.getInt("amount")!=1)throw new IllegalArgumentException();boolean added=store.claimSocialGift(uid,gift.id);Toast.makeText(SocialActivity.this,added?t("+1 indice dans ton inventaire","+1 hint in your inventory"):t("Déjà reçu, ou inventaire plein. Tu peux réessayer après avoir utilisé un indice.","Already received, or inventory full. Retry after using a hint."),Toast.LENGTH_LONG).show();refresh();}catch(Exception invalid){status.setText(t("Réception non finalisée. Réessaie : le reçu est conservé sans doublon.","Delivery not finalized. Retry: the receipt is retained without duplicates."));}}public void onError(String code){busy=false;status.setText(error(code));}});}
    private void refresh(){if(destroyed)return;if(!SocialClient.configured()||client.uid().isEmpty()){snapshot=null;busy=false;render();return;}busy=true;if(status!=null)status.setText(t("Actualisation…","Refreshing…"));client.refresh(new SocialClient.Listener(){public void onSnapshot(SocialClient.Snapshot value){if(destroyed)return;snapshot=value;busy=false;render();}public void onError(String code){if(destroyed)return;busy=false;status.setText(error(code));}});}
    private String error(String code){switch(code){case "SOCIAL_SIGN_IN_REQUIRED":return t("Reconnecte ton compte Google pour retrouver ton cercle.","Reconnect your Google account to find your circle.");case "SOCIAL_NOT_CONFIGURED":return t("Le cercle en ligne n'est pas configuré dans cette version. Aucun ami fictif n'est ajouté.","Online circle is not configured in this build. No sample friends are added.");case "SOCIAL_NOT_DEPLOYED":return t("Le service amis n'est pas encore déployé. Ton aventure reste disponible hors ligne.","The friend service is not deployed yet. Your adventure remains available offline.");case "INVALID_FRIEND_CODE":case "FRIEND_NOT_FOUND":return t("Vérifie le code ami de 16 caractères.","Check the 16-character friend code.");case "SELF_FRIEND":return t("C'est ton propre code ! Envoie-le à un ami.","That is your own code! Send it to a friend.");case "GIFT_DAILY_LIMIT":return t("Tes 3 cadeaux du jour sont envoyés. Reviens après minuit UTC.","Your 3 daily gifts are sent. Come back after midnight UTC.");case "GIFT_CLAIM_DAILY_LIMIT":return t("Tu as reçu 5 cadeaux aujourd’hui. Les autres restent dans ta boîte jusqu’à leur expiration.","You received 5 gifts today. The others stay in your mailbox until expiry.");case "GIFT_PAIR_LIMIT":return t("Cet ami a déjà reçu ton cadeau du jour.","This friend already received today's gift.");case "FRIEND_LIMIT":case "FRIEND_REQUEST_QUOTA":return t("Limite atteinte : 40 amis, 20 invitations actives et 20 nouvelles par jour.","Limit reached: 40 friends, 20 active invitations and 20 new ones per day.");case "GIFT_EXPIRED":return t("Ce cadeau a expiré après 7 jours.","This gift expired after 7 days.");case "INVALID_NICKNAME":return t("Choisis un surnom de 1 à 32 caractères, sans caractères de contrôle.","Choose a nickname of 1 to 32 characters, without control characters.");case "INCOMING_REQUEST_EXISTS":return t("Cet ami t'a déjà invité : accepte sa demande ci-dessous.","This friend already invited you: accept their request below.");case "RATE_LIMITED":return t("Un petit instant : réessaie dans une minute.","One moment: retry in a minute.");default:return t("Le cercle est indisponible. Vérifie ta connexion et réessaie. Aucune récompense n'est inventée hors ligne.","The circle is unavailable. Check your connection and retry. No offline rewards are invented.");}}
    private LinearLayout card(){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(5),dp(10),dp(5),dp(22));card.setBackground(SceneActionView.shelf());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(15);body.addView(card,p);return card;}
    private TextView label(LinearLayout parent,String value,int size,int color){com.androidhit.lumadrift.ui.PulseUi124.install(getAssets());TextView text=new TextView(this);text.setText(value);text.setTextColor(color);text.setTextSize(size);text.setTypeface(com.androidhit.lumadrift.ui.PulseUi124.face(size>=20?800:400));text.setLineSpacing(dp(3),1);text.setPadding(0,dp(10),0,dp(6));parent.addView(text);return text;}
    private void button(LinearLayout parent,String value,Runnable action,int color){SceneActionView actionView=SceneActionView.create(this,value,actionKind(value),color,action);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);parent.addView(actionView,p);}
    private ScenicUi.Kind actionKind(String value){
        if(value.startsWith("‹"))return ScenicUi.Kind.RETURN;
        if(value.equals(t("Mon compte Google","My Google account")))return ScenicUi.Kind.PROFILE;
        if(value.equals(t("Copier le code","Copy code")))return ScenicUi.Kind.KEY;
        if(value.equals(t("Enregistrer mon profil","Save my profile"))||value.equals(t("Accepter","Accept")))return ScenicUi.Kind.CONFIRM;
        if(value.equals(t("Envoyer une invitation","Send invitation")))return ScenicUi.Kind.MAIL;
        if(value.equals(t("Offrir 1 indice","Gift 1 hint"))||value.equals(t("Vérifier la réception","Check delivery"))||value.equals(t("Recevoir l'indice","Receive hint")))return ScenicUi.Kind.CHEST;
        if(value.equals(t("Refuser","Decline"))||value.equals(t("Retirer du cercle","Remove friend"))||value.equals(t("Annuler l'invitation","Cancel invitation")))return ScenicUi.Kind.CANCEL;
        return ScenicUi.Kind.RETRY;
    }
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override protected void onDestroy(){destroyed=true;if(client!=null)client.close();super.onDestroy();}
}
